def name_operands(region,address,operation):
 if region!='Station':return operation
 if address==0x6913:operation=operation.replace('JP #693D','JP @Station.ReturnModelDescriptionHover.Entry')
 if address==0x693E:operation=operation.replace('LD DE, #6945','LD DE, @Station.DrawModelDescriptionPanel.Entry').replace('CALL #CB64','CALL @Station.TestDrawPointer.Entry')
 if address==0x6945:operation=operation.replace('(#6933)','(@ModelDescriptionState.TopRow)').replace('CALL #C287','CALL @Station.DrawCaptionItem.Entry').replace('CALL #6952','CALL @Station.PrintModelDescription.Entry')
 return operation
